  "summary": "The code contains critical security vulnerabilities due to hardcoded credentials and insecure SMTP practices. Overall health is poor, requiring refactoring for dependency injection, performance optimization via connection pooling, and improved documentation.",
  "fixed_code": "import smtplib\nimport ssl\nimport os\nfrom email.message import EmailMessage\nfrom typing import Dict, Any\n\ndef send_email(to: str, subject: str, body: str, config: Dict[str, Any]) -> None:\n    \"\"\"Sends an email using the provided SMTP configuration.\n\n    Args:\n        to (str): Recipient email address.\n        subject (str): Email subject.\n        body (str): Email content.\n        config (Dict[str, Any]): SMTP configuration dictionary.\n    \"\"\"\n    msg = EmailMessage()\n    msg[\"From\"] = config[\"username\"]\n    msg[\"To\"] = to\n    msg[\"Subject\"] = subject\n    msg.set_content(body)\n\n    context = ssl.create_default_context()\n    with smtplib.SMTP(config[\"host\"], config[\"port\"]) as smtp:\n        if config.get(\"use_tls\", True):\n            smtp.starttls(context=context)\n        smtp.login(config[\"username\"], config[\"password\"])\n        smtp.send_message(msg)\n\n# Usage example:\n# config = {\n#     \"host\": os.environ.get(\"SMTP_HOST\", \"mail.example.com\"),\n#     \"port\": int(os.environ.get(\"SMTP_PORT\", 587)),\n#     \"username\": os.environ.get(\"SMTP_USER\"),\n#     \"password\": os.environ.get(\"SMTP_PASSWORD\"),\n#     \"use_tls\": True\n# }"
